import java.util.Scanner;

public class Main {
    static long MAX_INF = 17446744073709551616L;
    static long modulus, size_n, power_k;
    static long[][] dp_table = new long[18][250005];
    static long[] fact = new long[250005], inv_fact = new long[250005];

    static long fastExponentiation(long base, long exp) {
        long res = 1L, cur = base;
        while (exp > 0) {
            if ((exp & 1L) == 1L) res = (res * cur) % modulus;
            cur = (cur * cur) % modulus;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int a, int b) {
        return (((fact[a] * inv_fact[b]) % modulus) * inv_fact[a - b]) % modulus;
    }

    static long solve() {
        int i, j, mask;
        fact[0] = 1L;
        for (i = 1; i <= size_n; i++) {
            fact[i] = (fact[i - 1] * i) % modulus;
        }
        inv_fact[size_n] = fastExponentiation(fact[size_n], modulus - 2);
        for (i = size_n - 1; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % modulus;
        }
        for (i = 1; i <= size_n; i++) {
